INSERT INTO public.email_templates (workspace_id, slug, locale, subject, html_body, text_body, is_active) VALUES
(NULL, 'invite_otp', 'en', 'Your verification code — {brand}', '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Verification code</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px 40px 8px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Your verification code</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Use the code below to verify your invitation.</p></td></tr><tr><td align="center" style="padding:16px 40px 8px;"><div style="display:inline-block;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:10px;padding:16px 28px;color:#1e293b;font-size:30px;font-weight:700;letter-spacing:8px;font-family:Menlo,Consolas,monospace;">{code}</div></td></tr><tr><td style="padding:8px 40px 32px;text-align:center;"><p style="margin:0;color:#64748b;font-size:14px;line-height:22px;">This code expires in {expiry_minutes} minutes. If you did not request it, you can safely ignore this email.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', 'Your verification code: {code}. It expires in {expiry_minutes} minutes. — {brand}', true),
(NULL, 'invite_otp', 'fa', 'کد تأیید شما — {brand}', '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>کد تأیید</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:Tahoma,Segoe UI,Arial,sans-serif;direction:rtl;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px 40px 8px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">کد تأیید شما</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:26px;">برای تأیید دعوت‌نامه، از کد زیر استفاده کنید.</p></td></tr><tr><td align="center" style="padding:16px 40px 8px;"><div style="display:inline-block;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:10px;padding:16px 28px;color:#1e293b;font-size:30px;font-weight:700;letter-spacing:8px;font-family:Menlo,Consolas,monospace;direction:ltr;">{code}</div></td></tr><tr><td style="padding:8px 40px 32px;text-align:center;"><p style="margin:0;color:#64748b;font-size:14px;line-height:24px;">این کد تا {expiry_minutes} دقیقه دیگر معتبر است. اگر شما درخواست نکرده‌اید، این ایمیل را نادیده بگیرید.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', 'کد تأیید شما: {code} — این کد تا {expiry_minutes} دقیقه دیگر معتبر است. ({brand})', true),
(NULL, 'invite_otp', 'tr', 'Doğrulama kodunuz — {brand}', '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Doğrulama kodu</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px 40px 8px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Doğrulama kodunuz</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Davetinizi doğrulamak için aşağıdaki kodu kullanın.</p></td></tr><tr><td align="center" style="padding:16px 40px 8px;"><div style="display:inline-block;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:10px;padding:16px 28px;color:#1e293b;font-size:30px;font-weight:700;letter-spacing:8px;font-family:Menlo,Consolas,monospace;">{code}</div></td></tr><tr><td style="padding:8px 40px 32px;text-align:center;"><p style="margin:0;color:#64748b;font-size:14px;line-height:22px;">Bu kodun geçerlilik süresi {expiry_minutes} dakikadır. Bu isteği siz yapmadıysanız e-postayı yok sayabilirsiniz.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', 'Doğrulama kodunuz: {code}. Süresi {expiry_minutes} dakika. — {brand}', true);